rialization is needed.\n                let bytes = typeof session.metadata.publicSnapshotBytes === \"number\"\n                    ? session.metadata.publicSnapshotBytes\n                    : stableJson(prev).length;\n                for (let i = k; i < n; i++) bytes += stableJson(original[i]).length + 1;\n                if (cap > 0 && bytes > cap) dropOverCap();\n                else {\n                    for (let i = k; i < n; i++) prev.push(structuredClone(original[i]));\n                    session.metadata.publicSnapshotBytes = bytes;\n                    delete session.metadata.publicSnapshotCapped;\n                }\n                changed = true;\n            } else {\n                // Replacement (compression rewrote the history, restart\n                // divergence): full rebuild, measured before cloning as above.\n                const bytes = stableJson(original).length;\n                if (cap > 0 && bytes > cap) dropOverCap();\n                else {\n                    session.pluginSnapshot = structuredClone(original);\n                    session.metadata.publicSnapshotBytes = bytes;\n                    delete session.metadata.publicSnapshotCapped;\n                }\n                changed = true;\n            }\n        }\n        // The refs list must re-evaluate whenever the store object changed —\n        // CCR can gain entries between remembers without any history change,\n        // and the fork-time fail-closed check reads this list against the\n        // CURRENT store.\n        const storeChanged = snapshotRefsEvaluatedStore.get(session) !== session.contentStore;\n        if (changed || storeChanged) {\n            const previousRefs = session.metadata.publicSnapshotStoredRefs;\n            session.metadata.publicSnapshotStoredRefs = [...new Set([\n                ...(Array.isArray(previousRefs) ? previousRefs : []),\n                ...(session.pluginSnapshot ?? []).flatMap((m) => {\n                    const ref = session.state.messageRefs.byRaw[m.id];\n                    return ref && session.contentStore?.byRef[ref] ? [ref] : [];\n                }),\n            ])];\n            snapshotRefsEvaluatedStore.set(session, session.contentStore);\n        }\n        if (rawWire !== undefined) {\n            // The comparable verdict is a property of the wire body: hash it\n            // (native speed) and only re-parse + walk when the body actually\n            // changed, so a retry with an identical body stays cheap.\n            const wireHash = createHash(\"sha256\").update(rawWire).digest(\"hex\");\n            if (session.metadata.publicSnapshotWireHash !== wireHash) {\n                let comparable: boolean;\n                try {\n                    const wire = JSON.parse(rawWire.toString(\"utf8\")) as Record<string, unknown>;\n                    comparable = comparableHistory(wire.messages ?? wire.input ?? wire.contents);\n                } catch {\n                    comparable = false;\n                }\n                session.metadata.publicSnapshotWireHash = wireHash;\n                if (session.metadata.publicSnapshotTextComparable !== comparable) {\n                    session.metadata.publicSnapshotTextComparable = comparable;\n                    changed = true;\n                }\n            }\n        }\n        if (changed || storeChanged) markDirty(session);\n    }\n}\n\n// Launcher mode (#162): hosts that cannot attach per-request headers\n// (claude/codex spawned by `bili claude` / `bili codex`) pre-register their\n// conversation via POST /__bili/plugin/register — typically from a Claude\n// Code SessionStart hook or at codex spawn time. A pending register is\n// consumed by the FIRST model request that creates a NEW session afterwards\n// (server.ts binding step): that session becomes plugin-mode (native tools,\n// wire injection suppressed) and the conversation id becomes its tool-API key\n// — no x-bili-plugin headers required.\ntype PendingPluginRegister = { conversationId: string; agent: string; ts: number; parentConversationId?: string };\n\n/** Runtime-info protocol entry (#955): what the client's OWN config says it\n *  will run — reported at plugin bootstrap and on model switch, before (and\n *  independent of) any model request. Ranked in the native-window chain\n *  directly under the per-request header report; entries carry their model\n *  id and are only usable when that id matches the request's model (a stale\n *  post-switch entry must never size a different model). Entries carrying a\n *  conversationId are keyed by it (#1531), not by agent — one process runs\n *  many sessions (main + subagents) that share the agent name but report\n *  different windows, and a single per-agent slot let the last reporter\n *  clobber everyone else's entry. */\ntype PluginRuntimeInfo = {\n    agent: string;\n    model: string;\n    contextWindow?: number;\n    maxOutput?: number;\n    baseURL?: string;\n    conversationId?: string;\n    source: string;\n    ts: number;\n};\n\nconst pluginRuntimeTable = new Map<string, PluginRuntimeInfo>();\nconst pluginRuntimeByConversation = new Map<string, PluginRuntimeInfo>();\nconst MAX_PLUGIN_RUNTIME_ENTRIES = 32;\n\nfunction evictOldestRuntimeEntries(map: Map<string, PluginRuntimeInfo>): void {\n    while (map.size > MAX_PLUGIN_RUNTIME_ENTRIES) {\n        const oldest = map.keys().next().value;\n        if (oldest === undefined) break;\n        map.delete(oldest);\n    }\n}\n\nexport function recordPluginRuntimeInfo(entry: PluginRuntimeInfo): void {\n    const conv = entry.conversationId !== undefined && entry.conversationId.length > 0 ? entry.conversationId : undefined;\n    const table = conv !== undefined ? pluginRuntimeByConversation : pluginRuntimeTable;\n    table.delete(conv ?? entry.agent);\n    table.set(conv ?? entry.agent, entry);\n    evictOldestRuntimeEntries(table);\n}\n\n/** Latest runtime-info for an agent, usable for `model` only (undefined =\n *  no report, or a report for a different model). */\nexport function pluginRuntimeInfoFor(agent: string | undefined, model: string | undefined): PluginRuntimeInfo | undefined {\n    if (agent === undefined || model === undefined) return undefined;\n    const entry = pluginRuntimeTable.get(agent);\n    if (entry === undefined || entry.model !== model) return undefined;\n    return entry;\n}\n\n/** Latest runtime-info registered under a conversation id, usable for\n *  `model` only (#1531). */\nexport function pluginRuntimeInfoForConversation(conversationId: string | undefined, model: string | undefined): PluginRuntimeInfo | undefined {\n    if (conversationId === undefined || model === undefined) return undefined;\n    const entry = pluginRuntimeByConversation.get(conversationId);\n    if (entry === undefined || entry.model !== model) return undefined;\n    return entry;\n}\n\n/** The narrow conversation signal a header-less runtime-info lookup can\n *  match on (#1531): client conversation header → custom session header →\n *  body prompt_cache_key. Mirrors the identity chain's precedence at exactly\n *  the points where a reported conversationId could have been minted (omp\n *  stamps prompt_cache_key with its session uuid, #957/#1230); any divergence\n *  from the full binding identity degrades to a miss — legacy behavior —\n *  never a wrong hit. */\nexport function runtimeConversationId(headers: Record<string, string | string[] | undefined>, parsed: unknown, sessionHeaderName?: string): string | undefined {\n    const fromClient = clientConversationHeader(headers);\n    if (fromClient !== undefined && fromClient.length > 0) return fromClient;\n    const custom = sessionHeaderName !== undefined ? headerValue(headers, sessionHeaderName) : undefined;\n    if (custom !== undefined) return custom;\n    const pck = typeof parsed === \"object\" && parsed !== null ? (parsed as { prompt_cache_key?: unknown }).prompt_cache_key : undefined;\n    return typeof pck === \"string\" && pck.trim().length > 0 ? pck.trim() : undefined;\n}\n\n/** Accept the bootstrap/model-switch report. Body:\n *  { agent, model, contextWindow?, maxOutput?, baseURL?, source?,\n *    conversationId? } — agent+model are required; numbers are validated.\n *  Loopback-gated like every /__bili/plugin/* endpoint (the route lives\n *  under the same admin gate in server.ts). */\nexport function handlePluginRuntimeInfo(payload: string, res: import(\"node:http\").ServerResponse): void {\n    let parsed: unknown;\n    try {\n        parsed = JSON.parse(payload);\n    } catch {\n        res.writeHead(400, { \"content-type\": \"application/json\" });\n        res.end(JSON.stringify({ ok: false, error: \"invalid JSON\" }));\n        return;\n    }\n    const body = parsed as { agent?: unknown; model?: unknown; contextWindow?: unknown; maxOutput?: unknown; baseURL?: unknown; conversationId?: unknown; source?: unknown };\n    const str = (v: unknown, max: number) => (typeof v === \"string\" && v.length > 0 && v.length <= max ? v : undefined);\n    const num = (v: unknown) => (typeof v === \"number\" && Number.isFinite(v) && v > 0 ? Math.floor(v) : undefined);\n    const agent = str(body.agent, 64);\n    const model = str(body.model, 256);\n    if (agent === undefined || model === undefined) {\n        res.writeHead(400, { \"content-type\": \"application/json\" });\n        res.end(JSON.stringify({ ok: false, error: \"agent and model are required\" }));\n        return;\n    }\n    const conversationId = str(body.conversationId, 256);\n    recordPluginRuntimeInfo({\n        agent,\n        model,\n        contextWindow: num(body.contextWindow),\n        maxOutput: num(body.maxOutput),\n        baseURL: str(body.baseURL, 2048),\n        ...(conversationId !== undefined ? { conversationId } : {}),\n        source: str(body.source, 64) ?? \"client-config\",\n        ts: Date.now(),\n    });\n    res.writeHead(200, { \"content-type\": \"application/json\" });\n    res.end(JSON.stringify({ ok: true }));\n}\n\n/** Accept a takeover-attribution health report (#3581, contract reworked by\n *  #3651). Body: { agent, state: \"ok\"|\"none\"|\"threw\", refusals, since,\n *  [error], [endpoint] } — under the #3651 owner contract only DIAGNOSABLE\n *  failures (`threw` episodes: first refusal, state change to threw, count\n *  doubling, give-up latch) plus recovery notices reach this route; by-design\n *  agentless lanes never report. `error`/`endpoint` are bounded diagnostics\n *  that make the panel banner name the failure instead of a generic\n *  \"takeover broken\". Latest report wins per agent; the payload feeds\n *  /__bili/status + /__bili/overview (`attribution` field) and the web panel\n *  banner. */\nexport function handlePluginAttribution(payload: string, res: import(\"node:http\").ServerResponse): void {\n    let parsed: unknown;\n    try {\n        parsed = JSON.parse(payload);\n    } catch {\n        res.writeHead(400, { \"content-type\": \"application/json\" });\n        res.end(JSON.stringify({ ok: false, error: \"invalid JSON\" }));\n        return;\n    }\n    const body = parsed as { agent?: unknown; state?: unknown; refusals?: unknown; since?: unknown; error?: unknown; endpoint?: unknown };\n    const str = (v: unknown, max: number) => (typeof v === \"string\" && v.length > 0 && v.length <= max ? v : undefined);\n    const nonNeg = (v: unknown) => (typeof v === \"number\" && Number.isFinite(v) && v >= 0 ? Math.floor(v) : undefined);\n    const agent = str(body.agent, 64);\n    if (agent === undefined || (body.state !== \"ok\" && body.state !== \"none\" && body.state !== \"threw\")) {\n        res.writeHead(400, { \"content-type\": \"application/json\" });\n        res.end(JSON.stringify({ ok: false, error: \"agent and state (ok|none|threw) are required\" }));\n        return;\n    }\n    const error = str(body.error, 300);\n    const endpoint = str(body.endpoint, 200);\n    recordAttributionReport(agent, {\n        state: body.state,\n        refusals: nonNeg(body.refusals) ?? 0,\n        since: nonNeg(body.since) ?? 0,\n        ...(error !== undefined ? { error } : {}),\n        ...(endpoint !== undefined ? { endpoint } : {}),\n    });\n    res.writeHead(200, { \"content-type\": \"application/json\" });\n    res.end(JSON.stringify({ ok: true }));\n}\n\nconst MAX_PENDING_REGISTERS = 64;\n\nconst pendingRegisters: PendingPluginRegister[] = [];\n\n/** Queue a launcher-mode registration. `identity: true` means the host puts\n *  the SAME id on every model request (claude code: x-claude-code-session-id\n *  === CLAUDE_CODE_SESSION_ID) — bind by identity match only. `identity:\n *  false` (headless codex spawn) means requests carry no matching id — bind\n *  the next NEW session instead. Splitting the two keeps a foreign session\n *  from eating an identity registration it can never claim. */\nexport function queuePluginRegister(conversationId: string, agent: string, identity: boolean, parentConversationId?: string): void {\n    if (!identity) {\n        for (let i = 0; i < pendingRegisters.length; i++) {\n            if (pendingRegisters[i]!.conversationId === conversationId) {\n                pendingRegisters.splice(i, 1);\n                break;\n            }\n        }\n        pendingRegisters.push({ conversationId, agent, ts: Date.now(), ...(parentConversationId ? { parentConversationId } : {}) });\n        while (pendingRegisters.length > MAX_PENDING_REGISTERS) pendingRegisters.shift();\n    } else {\n        // #2408: a parent declaration is sticky for a conversation — a\n        // follow-up register WITHOUT one (claude's MCP shim re-registering the\n        // session the fork hook already declared) must not erase it.\n        const parent = parentConversationId ?? registeredIds.get(conversationId)?.parentConversationId;\n        registeredIds.set(conversationId, { agent, ...(parent ? { parentConversationId: parent } : {}) });\n        while (registeredIds.size > MAX_PENDING_REGISTERS) {\n            const oldest = registeredIds.keys().next().value;\n            if (oldest !== undefined) registeredIds.delete(oldest);\n        }\n    }\n}\n\n/** Headless registrations expire: a registration that no new session has\n *  claimed within this window was orphaned (the spawn never happened, or the\n *  session was created by some other path). Binding a stale one to an\n *  unrelated later session would turn that session into plugin mode with a\n *  foreign conversation id. */\nconst PENDING_REGISTER_TTL_MS = 10 * 60 * 1000;\n\n/** Take (and remove) the oldest eligible pending registration — called by the\n *  server when a model request resolves a NEW session, to bind that session\n *  into plugin mode. Expired (orphaned) registrations are dropped, never\n *  bound. Entries are appended in time order, so pruning from the front\n *  suffices. */\nexport function takePendingPluginRegister(\n    eligible: (pending: PendingPluginRegister) => boolean = () => true,\n): PendingPluginRegister | undefined {\n    const now = Date.now();\n    while (pendingRegisters.length > 0 && now - pendingRegisters[0]!.ts > PENDING_REGISTER_TTL_MS) {\n        pendingRegisters.shift();\n    }\n    const index = pendingRegisters.findIndex(eligible);\n    return index < 0 ? undefined : pendingRegisters.splice(index, 1)[0];\n}\nconst registeredIds = new Map<string, { agent: string; parentConversationId?: string }>();\n\n/** Identity-driven binding (#162): hosts whose model requests carry the SAME\n *  id the MCP shell registered (claude code: every request has\n *  x-claude-code-session-id === CLAUDE_CODE_SESSION_ID === the registered\n *  conversation id) bind the moment any of their requests shows up — no\n *  ordering race with the shell's initialize. */\nexport function consumePluginRegisterFor(conversationId: string): { agent: string; parentConversationId?: string } | undefined {\n    const entry = registeredIds.get(conversationId);\n    if (entry !== undefined) {\n        // The registration describes the CONVERSATION, not a one-shot token:\n        // switching models/upstreams mid-conversation resolves to a NEW\n        // session (session key = protocol|upstream|apiKey|conversation) that\n        // must still bind — omp TUI flows that switch models would otherwise\n        // drop back to wire mode on every switch. Keep the entry and refresh\n        // LRU order so the size cap evicts least-recently-active conversations.\n        registeredIds.delete(conversationId);\n        registeredIds.set(conversationId, entry);\n    }\n    return entry;\n}\n\nexport function handlePluginRegister(payload: string, res: import(\"node:http\").ServerResponse): void {\n    let parsed: { conversationId?: unknown; agent?: unknown; identity?: unknown; parentConversationId?: unknown };\n    try {\n        parsed = JSON.parse(payload) as { conversationId?: unknown; agent?: unknown; identity?: unknown };\n    } catch {\n        res.writeHead(400, { \"content-type\": \"application/json\" });\n        res.end(JSON.stringify({ ok: false, error: \"invalid JSON body\" }));\n        return;\n    }\n    const conversationId = typeof parsed.conversationId === \"string\" ? parsed.conversationId.trim() : \"\";\n    if (!conversationId) {\n        res.writeHead(400, { \"content-type\": \"application/json\" });\n        res.end(JSON.stringify({ ok: false, error: \"conversationId is required\" }));\n        return;\n    }\n    const agent = typeof parsed.agent === \"string\" && parsed.agent.trim() ? parsed.agent.trim() : \"launcher\";\n    // [#1333] optional declared derivation (pi RLM child): the parent\n    // conversation the proxy should seed this conversation from.\n    let parentConversationId = typeof parsed.parentConversationId === \"string\" ? parsed.parentConversationId.trim() : \"\";\n    if (parentConversationId === conversationId) parentConversationId = \"\";\n    queuePluginRegister(conversationId, agent, parsed.identity === true, parentConversationId || undefined);\n    res.end(JSON.stringify({ ok: true, conversationId, agent }));\n}\n\nexport function handlePluginCompact(payload: string, res: import(\"node:http\").ServerResponse): void {\n    let parsed: { conversationId?: unknown };\n    try {\n        parsed = JSON.parse(payload) as { conversationId?: unknown };\n    } catch {\n        res.writeHead(400, { \"content-type\": \"application/json\" });\n        res.end(JSON.stringify({ ok: false, error: \"invalid JSON body\" }));\n        return;\n    }\n    const conversationId = typeof parsed.conversationId === \"string\" ? parsed.conversationId.trim() : \"\";\n    if (!conversationId) {\n        res.writeHead(400, { \"content-type\": \"application/json\" });\n        res.end(JSON.stringify({ ok: false, error: \"conversationId is required\" }));\n        return;\n    }\n    const { session, entry } = resolveConversation(conversationId);\n    // #760: the verbatim-id fallback above can resolve a session with NO map\n    // entry (first call), so only the session itself gates execution.\n    if (!session) {\n        res.writeHead(404, { \"content-type\": \"application/json\" });\n        res.end(JSON.stringify({\n            ok: false,\n            error: entry\n                ? `unknown plugin conversation id \"${conversationId}\" (id registered but session not resident)`\n                : `unknown plugin conversation id \"${conversationId}\" (no model request has arrived with this conversation id yet)`,\n        }));\n        return;\n    }\n    markCompactionBoundary(session);\n    if (entry) entry.lastSeen = Date.now();\n    res.end(JSON.stringify({ ok: true, conversationId }));\n}\n\n// #2322: the host named the conversation (pi /name) — remember it as the\n// session's display title. B-channel design: a dedicated endpoint (instead\n// of a request header) so set/rename/CLEAR are all expressible (empty name =\n// clear, falling display back to the derived first-message title) and the\n// name lands immediately, not on the next model request.\nconst HOST_TITLE_MAX = 200;\n\nexport function handlePluginSessionName(payload: string, res: import(\"node:http\").ServerResponse): void {\n    let parsed: { conversationId?: unknown; name?: unknown };\n    try {\n        parsed = JSON.parse(payload) as { conversationId?: unknown; name?: unknown };\n    } catch {\n        res.writeHead(400, { \"content-type\": \"application/json\" });\n        res.end(JSON.stringify({ ok: false, error: \"invalid JSON body\" }));\n        return;\n    }\n    const conversationId = typeof parsed.conversationId === \"string\" ? parsed.conversationId.trim() : \"\";\n    if (!conversationId) {\n        res.writeHead(400, { \"content-type\": \"application/json\" });\n        res.end(JSON.stringify({ ok: false, error: \"conversationId is required\" }));\n        return;\n    }\n    if (typeof parsed.name !== \"string\") {\n        res.writeHead(400, { \"content-type\": \"application/json\" });\n        res.end(JSON.stringify({ ok: false, error: \"name must be a string (empty clears)\" }));\n        return;\n    }\n    const { session, entry } = resolveConversation(conversationId);\n    if (!session) {\n        res.writeHead(404, { \"content-type\": \"application/json\" });\n        res.end(JSON.stringify({\n            ok: false,\n            error: entry\n                ? `unknown plugin conversation id \"${conversationId}\" (id registered but session not resident)`\n                : `unknown plugin conversation id \"${conversationId}\" (no model request has arrived with this conversation id yet)`,\n        }));\n        return;\n    }\n    let name = parsed.name.replace(/\\s+/g, \" \").trim();\n    if (name.length > HOST_TITLE_MAX) name = name.slice(0, HOST_TITLE_MAX);\n    if (name) session.meta.hostTitle = name;\n    else delete session.meta.hostTitle;\n    markDirty(session);\n    if (entry) entry.lastSeen = Date.now();\n    res.end(JSON.stringify({ ok: true, conversationId }));\n}\n\n// #1685: the conversation_id tool parameter is GONE from the manifest — the\n// model must never see or echo a conversation id (zero-injection identity:\n// the proxy routes by outbound tool_use witness / body id / single-active\n// arbitration; see tool-ring.ts). Wire-mode injection serves the kernel\n// constants directly, which never carried the param.\n\nexport function handlePluginManifest(res: import(\"node:http\").ServerResponse, config: Config, toolPrompts?: ToolPrompts): void {\n    // #1192: hosts register whatever the manifest serves verbatim (pi/omp/dsh/\n    // opencode native plugins, MCP shims), so advertising an opt-in tool this\n    // proxy's config leaves disabled guarantees a rejected call the moment the\n    // model uses it. Advertise absorb/acp_rule only when base-config enabled;\n    // per-request provider/model overrides may still differ (conservative: the\n    // manifest never advertises what the base config disables) and per-session\n    // enablement stays enforced at execution (isProxyToolFor / executeProxyTool).\n    // #1359: the advertised name is the base-config toolName, matching the\n    // plugin-lane gate (which adjudicates the same base block).\n    // #3243: toolPrompts is the pack surface's tool descriptions, resolved by the\n    // caller from the GLOBAL compress settings — the manifest has no route/model\n    // context (hosts fetch it before any request arrives), so provider/model-level\n    // promptPack still shapes each request's system prompt while registered tool\n    // descriptions follow the top-level pack only. Applied exactly like the wire\n    // injector (applyAcpToolOverrides on the ACP core arrays before extras merge).\n    const absorbOn = absorbEnabled(config);\n    const absorbName = config.absorb?.toolName ?? ABSORB_TOOL_NAME;\n    const absorbTools = absorbOn ? absorbToolsFor(absorbName) : undefined;\n    const rulesOn = rulesEnabled(config);\n    // [#1271] acp_retrieve is advertised only while the base config enables CCR (same\n    // #1192 conservative rule as absorb/acp_rule). The proxy wires it on the anthropic/\n    // openai lanes in plugin mode; the responses wire is deliberately NOT advertised —\n    // that proxy disarms CCR there, so advertising would break #1192.\n    const ccrOn = config.ccr?.enabled === true;\n    const ccrName = config.ccr?.toolName ?? RETRIEVE_TOOL_NAME;\n    const ccrTools = ccrOn ? retrieveToolsFor(ccrName) : undefined;\n    // #3400: acp_read_original_image restores the full-resolution original of a\n    // downscaled image from local session storage. Same conservative #1192\n    // rule as acp_retrieve: advertised only while the base knob enables the\n    // rescale pass (disabled ⇒ no [bili] note ever names it, so a registered\n    // copy could only be dead weight). Execution stays always-allowed: it is\n    // an idempotent local read, never a state mutation.\n    const rescaleOn = imageRescaleEnabled();\n    // #1712: decompress's startId/endId (range restore) executes only on CCR-armed\n    // sessions, so the manifest advertises them only when the base config enables\n    // CCR (#1345 plugin policy = base block verbatim) — same conservative #1192\n    // rule as acp_retrieve above. CCR-off manifests serve the no-range variants so\n    // a registered agent never sees range fields execution would refuse.\n    const externalSummary = externalSummaryEnabled(config);\n    // #3252: the manifest serves code-mode harnesses too (dsh registers the\n    // dsh-bili plugin and its \"PTC\" preset renders these descriptions as the\n    // run_code SDK docs). The binding note on the ACP entries teaches both\n    // calling conventions, so the model neither slips a direct call the\n    // harness will reject nor dodges the direct call native hosts expect.\n    // #3243: the pack surface's tool descriptions (toolPrompts) override the\n    // stock descriptions where a promptPack declares its own.\n    const acpAnthropic = withAcpNotes(withExternalSummaryTools(applyAcpToolOverrides(ccrOn ? BILI_ACP_TOOLS_ANTHROPIC : BILI_ACP_TOOLS_ANTHROPIC_NO_RANGE, toolPrompts), externalSummary), \"binding\");\n    const acpOpenai = withAcpNotesOpenAI(withExternalSummaryTools(applyAcpToolOverrides(ccrOn ? BILI_ACP_TOOLS_OPENAI : BILI_ACP_TOOLS_OPENAI_NO_RANGE, toolPrompts), externalSummary), \"binding\");\n    // Responses wire: plugin mode structurally disarms CCR there (#1271 —\n    // PLUGIN_CCR_WIRES excludes it), so range restore can never execute for a\n    // registered agent on that wire — always the no-range variant, mirroring\n    // how ccrTools above is never spread into the responses array.\n    const acpResponses = withAcpNotes(withExternalSummaryTools(applyAcpToolOverrides(BILI_ACP_TOOLS_RESPONSES_NO_RANGE, toolPrompts), externalSummary), \"binding\");\n    res.writeHead(200, { \"content-type\": \"application/json\" });\n    res.end(JSON.stringify({\n        ok: true,\n        protocolVersion: PLUGIN_PROTOCOL_VERSION,\n        proxy: \"billion-context\",\n        version: VERSION,\n        commit: BUILD_COMMIT,\n        toolNames: [...PROXY_TOOL_NAMES, ...(absorbTools ? [absorbName] : []), ...(rulesOn ? [RULE_TOOL_NAME] : []), ...(ccrOn ? [ccrName] : []), ...(rescaleOn ? [READ_ORIGINAL_IMAGE_TOOL_NAME] : [])],\n        tools: {\n            anthropic: [...acpAnthropic, ...(absorbTools ? [absorbTools.anthropic] : []), ...(rulesOn ? [RULE_TOOL] : []), ...(ccrTools ? [ccrTools.anthropic] : []), ...(rescaleOn ? [READ_ORIGINAL_IMAGE_TOOL] : [])],\n            openai: [...acpOpenai, ...(absorbTools ? [absorbTools.openai] : []), ...(rulesOn ? [RULE_TOOL_OPENAI] : []), ...(ccrTools ? [ccrTools.openai] : []), ...(rescaleOn ? [READ_ORIGINAL_IMAGE_TOOL_OPENAI] : [])],\n            responses: [...acpResponses, ...(absorbTools ? [absorbTools.responses] : []), ...(rulesOn ? [RULE_TOOL_RESPONSES] : []), ...(rescaleOn ? [READ_ORIGINAL_IMAGE_TOOL_RESPONSES] : [])],\n        },\n        headers: { agent: PLUGIN_AGENT_HEADER, conversation: PLUGIN_CONVERSATION_HEADER, contextWindow: PLUGIN_CONTEXT_WINDOW_HEADER, maxOutput: PLUGIN_MAX_OUTPUT_HEADER, model: PLUGIN_MODEL_HEADER, instructionsMutable: PLUGIN_INSTRUCTIONS_MUTABLE_HEADER, compression: PLUGIN_COMPRESSION_HEADER },\n        toolEndpoint: \"/__bili/plugin/tool\",\n        statusEndpoint: \"/__bili/plugin/status\",\n        runtimeInfoEndpoint: \"/__bili/plugin/runtime-info\",\n        // #2652: maxToolDurationMs = the budget's totalTimeoutMs ceiling, so agent-side\n        // bridges size their compress-call HTTP wait to the real server bound instead of a\n        // fixed constant. Absent when the chain is off (classic summaries commit locally).\n        capabilities: { ...(externalSummary ? { externalSummary: { enabled: true, summaryOptional: true, submittedSummary: \"hint\", maxToolDurationMs: externalSummaryMaxToolDurationMs(config) } } : {}), fork: { protocolVersion: 2, acceptsProtocolVersions: [1, 2], endpoint: \"/__bili/plugin/fork\", snapshotEndpoint: \"/__bili/plugin/snapshot\" } },\n    }));\n}\n\nexport type PluginToolDeps = {\n    core: CompressionCore;\n    config: Config;\n    log: (level: string, msg: string) => void;\n    // Browser-reachable origin of THIS proxy (http://host:port) for the human-facing\n    // Web UI deep links inside panels/reports; absent in test harnesses/embeds.\n    webOrigin?: string;\n    // #4571: true when the answering engine is the in-process inline lane —\n    // the status panel appends \" · inline\" so a screenshot names its mode.\n    inlineLane?: boolean;\n    signal?: AbortSignal;\n};\n\n/** Reverse-lookup the conversation id bound to a session id. #656: the\n *  status endpoint's fallback branch picks the latest active SESSION, but a\n *  caller that needs to ADOPT it (an MCP shim whose captured conversation id\n *  went stale after the host resumed) must be told the session's conversation\n *  id, not have its own stale id echoed back. Most-recently-seen binding wins\n *  when several conversations share one session. */\nfunction conversationIdForSession(sessionId: string): string | undefined {\n    let bestId: string | undefined;\n    let bestSeen = -Infinity;\n    for (const [cid, entry] of conversations) {\n        if (entry.sessionId === sessionId && entry.lastSeen > bestSeen) {\n            bestId = cid;\n            bestSeen = entry.lastSeen;\n        }\n    }\n    return bestId;\n}\n\n/** Native session ids outrank lookup aliases: shared prompt_cache_key values\n *  must not redirect a parent to a child. Repair legacy conflicting mappings\n *  on lookup; unknown ids still create no session. */\nexport function resolveConversation(conversationId: string): { session: Session | undefined; entry?: ConversationEntry } {\n    let entry = conversations.get(conversationId);\n    let session = peekSession(conversationId) ?? (entry ? peekSession(entry.sessionId) : undefined);\n    if (!session) {\n        session = findSessionByCanonicalId(conversationId);\n    }\n    if (session && entry?.sessionId !== session.id) {\n        recordPluginSession(conversationId, session.id);\n        entry = conversations.get(conversationId);\n    }\n    return { session, entry };\n}\n\n// #2620: ref is null exactly when the message is intentionally unaddressable\n// (kernel-protected: no numeric ref issued). The kernel's internal sentinel\n// never crosses this boundary — null IS the protocol's \"no ref\" value.\ntype ForkIdentity = { rawId: string; ref: string | null; identityHash: string };\n\n// Only inspect message content, not arbitrary tool arguments containing a `type` key.\nfunction comparableHistory(value: unknown): boolean {\n    if (value === null || typeof value === \"string\") return true;\n    if (Array.isArray(value)) return value.every(comparableHistory);\n    if (!value || typeof value !== \"object\") return false;\n    const part = value as Record<string, unknown>;\n    if (part.type !== undefined && ![\"message\", \"text\", \"input_text\", \"output_text\", \"tool_use\", \"tool_result\", \"function_call\", \"function_call_output\"].includes(String(part.type))) return false;\n    if (part.type === \"tool_use\" || part.type === \"function_call\") return true;\n    if (part.audio !== undefined && part.audio !== null) return false;\n    if (part.content !== undefined) return comparableHistory(part.content);\n    if (part.output !== undefined) return comparableHistory(part.output);\n    if (part.parts !== undefined) return comparableHistory(part.parts);\n    return typeof part.text === \"string\" || Array.isArray(part.tool_calls);\n}\ntype ForkRequest = {\n    protocolVersion: 1 | 2;\n    parentConversationId: string;\n    childConversationId: string;\n    parentRevision: string;\n    branchPoint: { messageCount: number; orderHash: string };\n    orderedMessages: ForkIdentity[];\n    idempotencyKey: string;\n};\n\nfunction stableJson(value: unknown): string {\n    if (Array.isArray(value)) return `[${value.map(stableJson).join(\",\")}]`;\n    if (value !== null && typeof value === \"object\") {\n        const obj = value as Record<string, unknown>;\n        return `{${Object.keys(obj).filter((k) => obj[k] !== undefined).sort().map((k) => `${JSON.stringify(k)}:${stableJson(obj[k])}`).join(\",\")}}`;\n    }\n    return JSON.stringify(value) ?? \"null\";\n}\n\nfunction forkHash(value: unknown): string {\n    return createHash(\"sha256\").update(stableJson(value), \"utf8\").digest(\"hex\");\n}\n\nfunction forkOrderHash(messages: ForkIdentity[]): string {\n    return createHash(\"sha256\").update(JSON.stringify(messages), \"utf8\").digest(\"hex\");\n}\n\nfunction forkToolIsError(message: CoreMessage): boolean {\n    return (message as CoreMessage & { toolIsError?: boolean }).toolIsError === true;\n}\n\nexport function forkMessageIdentityHash(message: CoreMessage): string {\n    return forkHash([message.role, message.contentType, message.text ?? null, message.toolName ?? null, message.toolCallId ?? null, message.thinkingTokens ?? null, message.summaryOfBlockId ?? null, forkToolIsError(message)]);\n}\n\n/** #2077 CoW view equality for rememberPluginMessages' prefix walk: compares\n *  exactly the field set forkMessageIdentityHash digests, plus id. An id\n *  prefix match alone would keep a stale snapshot when a resent history flips\n *  an adapter-attached flag (toolIsError) under unchanged ids — the snapshot\n *  must track every byte fork matching can see. If an adapter ever attaches a\n *  new runtime field, it MUST be added here and to forkMessageIdentityHash\n *  together. */\nfunction sameSnapshotView(a: CoreMessage, b: CoreMessage): boolean {\n    return a.id === b.id && a.role === b.role && a.contentType === b.contentType\n        && a.text === b.text && a.toolName === b.toolName && a.toolCallId === b.toolCallId\n        && a.thinkingTokens === b.thinkingTokens && a.summaryOfBlockId === b.summaryOfBlockId\n        && forkToolIsError(a) === forkToolIsError(b);\n}\n\n/** #3741: classified verdict of the first-request inherited-prefix gate.\n *  `reason` is a stable failure class plus minimal evidence — safe to log and\n *  echo to the client (truncated ids/hashes only, never message content).\n *  Each evidence part appears only when ITS OWN check failed — a cell whose ref\n *  mapping was pruned (id+hash intact) reports ref-broken alone, not drift. */\ntype PublicForkPrefixVerdict = { ok: true } | { ok: false; reason: string };\n\nconst FORK_PREFIX_ID_PREVIEW = 16;\nconst FORK_PREFIX_HASH_PREVIEW = 12;\n\nfunction forkPrefixPreview(value: string): string {\n    return value.length > 0 ? value.slice(0, FORK_PREFIX_ID_PREVIEW) : \"-\";\n}\n\n/** Read under the session lock; compare ordered semantics, never just an id set.\n *  #3741: returns a classified verdict instead of a bare boolean — the 409 path\n *  was a total diagnostic blind spot. The classes separate the three drift\n *  shapes that matter for triage: id-drift (re-minted/renormalized history —\n *  version skew or host body rewrite), hash-drift-under-same-id (adapter-attached\n *  flags like toolIsError flipped under unchanged bytes), and structural shape\n *  changes (shorter replay, unmappable body). Any unexpected error stays\n *  fail-closed exactly as before. */\nexport function publicForkInputCheck(session: Session, protocol: WireProtocol, parsed: unknown): PublicForkPrefixVerdict {\n    const prefix = session.pluginSnapshot;\n    if (session.metadata.publicForkReceipt === undefined) return { ok: false, reason: \"receipt-missing\" };\n    if (!prefix) return { ok: false, reason: \"snapshot-missing\" };\n    try {\n        const incoming = incomingCoreMessages(protocol, parsed);\n        if (incoming === null) return { ok: false, reason: `incoming-unmappable (protocol=${protocol})` };\n        if (incoming.length < prefix.length) return { ok: false, reason: `prefix-longer-than-incoming (expected=${prefix.length} incoming=${incoming.length})` };\n        for (let index = 0; index < prefix.length; index += 1) {\n            const expected = prefix[index]!;\n            const candidate = incoming[index]!;\n            const ref = session.state.messageRefs.byRaw[expected.id];\n            // #2620: protected tool calls/results carry the kernel BLOCKED sentinel (no numeric\n            // ref, byRef never holds it) — a legitimate state, not a broken mapping.\n            const refOk = ref !== undefined && (ref === BLOCKED_REF || session.state.messageRefs.byRef[ref] === expected.id);\n            const idOk = candidate.id === expected.id;\n            const expectedHash = forkMessageIdentityHash(expected);\n            const candidateHash = forkMessageIdentityHash(candidate);\n            if (!refOk || !idOk || candidateHash !== expectedHash) {\n                const parts = [`cell-mismatch@${index}`];\n                if (!refOk) parts.push(`ref-broken (rawId=${forkPrefixPreview(expected.id)} ref=${ref ?? \"MISSING\"})`);\n                if (!idOk) parts.push(`id-drift expected=${forkPrefixPreview(expected.id)} got=${forkPrefixPreview(candidate.id)}`);\n                else if (candidateHash !== expectedHash) parts.push(`hash-drift-under-same-id role=${candidate.role} expected-hash=${expectedHash.slice(0, FORK_PREFIX_HASH_PREVIEW)} got-hash=${candidateHash.slice(0, FORK_PREFIX_HASH_PREVIEW)}`);\n                return { ok: false, reason: parts.join(\" \") };\n            }\n        }\n        return { ok: true };\n    } catch (err) {\n        return { ok: false, reason: `projection-error (${err instanceof Error ? err.message : String(err)})` };\n    }\n}\n\n/** Cheap, cache-backed read of the fork parentRevision. forkSnapshot() is a\n *  pure function of the session content and status polling would otherwise\n *  re-hash the entire history (plus the CCR store, payload by payload) on\n *  every call (#2017 review item E); revisionEpoch — bumped by markDirty on\n *  every mutation — keys the cache, so an unchanged session costs O(1).\n *  Same fail-closed errors as forkSnapshot itself propagate to the caller. */\nfunction sessionRevisionOf(session: Session): string {\n    const epoch = session.revisionEpoch ?? 0;\n    const cache = session.pluginRevisionCache;\n    if (cache && cache.epoch === epoch) return cache.revision;\n    const revision = forkSnapshot(session).parentRevision;\n    session.pluginRevisionCache = { epoch, revision };\n    return revision;\n}\n\n/** #5140 item 4: a non-retained parent cold-restored in shadow mode loses its\n *  resident pluginSnapshot (persist.ts retention gate) even though index.db\n *  still holds the independently recorded unfolded raw tail. Rebuild that tail\n *  through its LOGICAL tailSeqs projection (never append-log order, never the\n *  folded envelope) and prove it IS this session's complete ordered history\n *  before it may stand in for the snapshot: every seq resolves (zero gaps), ids\n *  equal state.lastPassIds in exact order, and it sits under the UTF-8 byte cap.\n *  Pure — never mutates the session. Any miss returns null so callers fail\n *  closed exactly as before. */\n// #5140 CI-red follow-up: every reconstruction miss records WHICH gate fired,\n// so a 409 SNAPSHOT_UNAVAILABLE is diagnosable from server logs and the\n// client-visible error instead of being one silent null among five.\nconst reconMissGate = new Map<string, { gate: string; at: number }>();\nconst reconMissLastLogMs = new Map<string, number>();\n\nfunction reconMiss(session: Session, gate: string, detail?: string): null {\n    const why = detail ? `${gate} ${detail}` : gate;\n    const key = `${session.id}:${gate}`;\n    const now = Date.now();\n    if (now - (reconMissLastLogMs.get(key) ?? 0) >= 10_000) {\n        reconMissLastLogMs.set(key, now);\n        loggerLog(\"warn\", `[plugin] raw-tail reconstruction unavailable for ${session.id} (${why}) — snapshot/fork falls back to the legacy path`);\n    }\n    reconMissGate.set(session.id, { gate: why, at: now });\n    return null;\n}\n\nfunction reconMissReason(sessionId: string): string | undefined {\n    const hit = reconMissGate.get(sessionId);\n    return hit && Date.now() - hit.at < 30_000 ? hit.gate : undefined;\n}\n\n// #5188 round 3: #5140's flake was a timing race — the ctor's first sidecar open\n// died on a transient disk spike under shard load, the resource cleared\n// milliseconds later, and the cold-restore snapshot request arrived before any\n// post-spike recovery attempt had fired. When reconstruction is actually needed\n// and the sidecar is merely MISSING (recoverable without restart), the two\n// user-visible 409 paths wait a bounded moment for that self-recovery instead\n// of racing it. Latched-disabled never waits — waiting cannot help there. The\n// pre-lock read of pluginSnapshot/lastPassIds is fine for gating: a stale answer\n// only costs one unnecessary wait or skips one (same immediate 409 as before).\nasync function waitForReconstructionReplicas(session: Session): Promise<void> {\n    if (session.pluginSnapshot !== undefined) return;\n    const expected = session.state.lastPassIds;\n    if (!expected || expected.length === 0) return;\n    const store = getStore();\n    if (store.replicasAvailable()) return;\n    if (store.sidecarDownReason() !== \"sidecar-missing\") return;\n    await store.waitForReplicas();\n}\n\nfunction reconstructRawTailForFork(session: Session): CoreMessage[] | null {\n    const expected = session.state.lastPassIds;\n    if (!expected || expected.length === 0) return reconMiss(session, \"empty-lastPassIds\");\n    const store = getStore();\n    if (!store.replicasAvailable()) return reconMiss(session, \"replicasUnavailable\", store.sidecarDownReason());\n    const seqs = store.unifiedTailSeqs(session.id);\n    if (!seqs || seqs.length === 0) return reconMiss(session, \"empty-tailSeqs\", `expected=${expected.length}`);\n    const rows = store.unifiedTailViewRows(session.id);\n    if (!rows) return reconMiss(session, \"null-tailViewRows\", `seqs=${seqs.length}`);\n    const bySeq = new Map<number, string>();\n    for (const row of rows) bySeq.set(row.seq, row.content);\n    const out: CoreMessage[] = [];\n    for (const seq of seqs) {\n        const content = bySeq.get(seq);\n        if (content === undefined) return reconMiss(session, \"gap-tailRow\", `seq=${seq}/${seqs.length} rows=${rows.length}`); // gap: a logical seq has no stored row\n        let msg: CoreMessage;\n        try { msg = JSON.parse(content) as CoreMessage; } catch { return reconMiss(session, \"unparseable-row\", `seq=${seq}`); }\n        if (typeof msg.id !== \"string\" || typeof msg.role !== \"string\") return reconMiss(session, \"bad-row-shape\", `seq=${seq}`);\n        out.push(msg);\n    }\n    if (out.length !== expected.length) return reconMiss(session, \"length-mismatch\", `rows=${out.length} expected=${expected.length}`);\n    for (let i = 0; i < out.length; i += 1) if (out[i]!.id !== expected[i]) return reconMiss(session, \"id-mismatch\", `index=${i}`);\n    const cap = publicSnapshotCapBytes();\n    if (Buffer.byteLength(stableJson(out), \"utf8\") > cap) return reconMiss(session, \"cap-exceeded\");\n    reconMissGate.delete(session.id);\n    return out;\n}\n\nfunction forkSnapshot(session: Session, source?: CoreMessage[] | null) {\n    const messages = source ?? session.pluginSnapshot ?? reconstructRawTailForFork(session);\n    if (!messages) {\n        const capped = session.metadata.publicSnapshotCapped === true;\n        const base = capped ? \"raw snapshot exceeded the retention cap (BILI_PUBLIC_SNAPSHOT_CAP_BYTES); fork is refused rather than retaining an unbounded raw copy\" : \"raw snapshot unavailable; send a fresh plugin model request\";\n        // the capped base names the refusal itself; a gate recorded under it is\n        // incidental (reconstruction may bail before reaching the cap check)\n        const why = capped ? undefined : reconMissReason(session.id);\n        throw new Error(why ? `${base} [reconstruction: ${why}]` : base);\n    }\n    if (session.metadata.publicSnapshotTextComparable === false || messages.some((m) => (m.thinkingTokens ?? 0) > 0)) throw new Error(\"multimodal or opaque content cannot be compared by text\");\n    const store = contentStoreOf(session);\n    const expectedStoredRefs = session.metadata.publicSnapshotStoredRefs;\n    if (Array.isArray(expectedStoredRefs) && expectedStoredRefs.some((ref) => typeof ref !== \"string\" || !store.byRef[ref])) throw new Error(\"CCR original index unavailable\");\n    const indexedHashes = new Set(Object.values(store.byRef).map((entry) => entry.hash));\n    if (Object.entries(store.byHash).some(([hash, text]) => !indexedHashes.has(hash) || typeof text !== \"string\" || createHash(\"sha256\").update(text, \"utf8\").digest(\"hex\") !== hash)) throw new Error(\"CCR original payload/index inconsistent\");\n    if (Object.entries(store.byRef).some(([ref, entry]) => typeof store.byHash[entry.hash] !== \"string\" || (session.state.messageRefs.byRaw[entry.rawId] !== undefined && (session.state.messageRefs.byRaw[entry.rawId] !== ref || session.state.messageRefs.byRef[ref] !== entry.rawId)))) throw new Error(\"CCR original alias inconsistent\");\n    const orderedMessages = messages.map((m, i): ForkIdentity => {\n        const ref = session.state.messageRefs.byRaw[m.id];\n        // #2620: protected tool calls/results map to the kernel BLOCKED sentinel by design\n        // (kernel assignRefs) — no numeric ref exists and byRef never holds it, so the\n        // bidirectional check applies only to numeric refs; genuine corruption still fails.\n        // #2676: name the offending message in the error — a bare invariant string gave no\n        // clue which of hundreds of snapshot entries broke the mapping.\n        if (!ref || (ref !== BLOCKED_REF && session.state.messageRefs.byRef[ref] !== m.id)) throw new Error(`raw/ref mapping inconsistent (msg ${i + 1}/${messages.length} role=${m.role} tool=${m.toolName ?? \"-\"} ref=${ref ?? \"MISSING\"} rawId=${m.id.slice(0, 16)})`);\n        const entry = store.byRef[ref];\n        const placeholder = m.text ? parseStoredPlaceholder(m.text) : null;\n        if ((entry && (entry.rawId !== m.id || typeof store.byHash[entry.hash] !== \"string\")) || (placeholder && (placeholder.ref !== ref || !entry))) throw new Error(\"CCR original unavailable or alias inconsistent\");\n        return { rawId: m.id, ref: ref === BLOCKED_REF ? null : ref, identityHash: forkMessageIdentityHash(m) };\n    });\n    // #2671 Phase 2b (fork protocol v2): the revision token is now\n    // {sessionId, seq, active block set} — stable across any churn that does\n    // not move the ordered snapshot or the active blocks (v1 hashed the whole\n    // state incl. every CCR payload, so unrelated store activity flipped it;\n    // see forkParentRevisionLegacy). The deep fork checks (orderHash +\n    // byte-exact prefix comparison below) remain the correctness boundary;\n    // the revision is only the cheap early-exit token.\n    const activeBlockSet = session.state.blocks.filter((b) => b.active).map((b) => b.blockId).sort();\n    const parentRevision = forkHash({ sessionId: session.id, seq: orderedMessages.length, blockSet: activeBlockSet });\n    return { protocolVersion: 2, status: \"exact\", sessionId: session.id, parentRevision, orderHash: forkOrderHash(orderedMessages), orderedMessages, messages: messages.map((m, i) => ({ rawId: m.id, ref: orderedMessages[i]!.ref, role: m.role, text: m.text, toolName: m.toolName, toolCallId: m.toolCallId, contentType: m.contentType, toolIsError: forkToolIsError(m) })) };\n}\n\n/** #2671 Phase 2b transition digest: fork protocol v1 hashed the ENTIRE\n *  snapshot ({sessionId, messages, state, blockContents, contentStore}) so\n *  any unrelated store churn (post-snapshot CCR activity, stats nudges,\n *  image-restore rewrites) flipped parentRevision and forced spurious 409s.\n *  v2 hashes only {sessionId, seq, active block set}. The POST handler still\n *  ACCEPTS a v1 hash for one transition version (clients that snapshotted\n *  under an older proxy); this legacy digest is recomputed ONLY on that\n *  fallback path — GET snapshot and status polling never pay O(store)\n *  hashing. Drop this (and the fallback) once no v1 client can exist. */\nexport function forkParentRevisionLegacy(session: Session): string {\n    const messages = session.pluginSnapshot;\n    if (!messages) throw new Error(\"raw snapshot unavailable\");\n    const store = contentStoreOf(session);\n    const state = { ...session.state };\n    return forkHash({ sessionId: session.id, messages, state, blockContents: Object.fromEntries(session.blockContents), contentStore: store });\n}\n\n// #4942: async — on network storage backends the existence probes must be\n// able to reach the DB (the sync facade misses by design there). Materialization\n// must ride the SAME async seam: a sync getSession after an async probe would\n// mint an EMPTY resident ghost for a DB-only id, and that ghost then poisons\n// every later getSessionAsync of the id for the process lifetime.\nasync function resolveForkConversation(id: string): Promise<Session | undefined> {\n    if (peekSession(id)) return peekSession(id);\n    if (await getStore().loadAsync(id)) return getSessionAsync(id);\n    const { session, entry } = resolveConversation(id);\n    if (session) return session;\n    const persistedId = entry?.sessionId ?? id;\n    if (!(await getStore().loadAsync(persistedId))) return undefined;\n    return getSessionAsync(persistedId);\n}\n\n/** #2601 freshness window for persona-lineage following — same family as\n *  SPLIT_CANARY_FRESH_MS (splitSessionWarnings): a fork that has not carried\n *  traffic for this long is not \"live\" anymore and the parent id routes home. */\nconst PERSONA_LINEAGE_FRESH_MS = 10 * 60 * 1000;\n\n/** #2948: does the session hold usable refs? A `|sub:` descendant that never\n *  rendered a message holds none — the aux/side-lane shape: dsh auto-review\n *  blobs fork onto their own lane and carry perpetual traffic (stats.requests\n *  bumped, kernel state untouched / turns failing mid-prepare), so they look\n *  \"live\" under every freshness criterion yet can serve NOTHING a management\n *  call needs. Every compress/decompress/acp_status routed there fails\n *  \"every ref is unknown to this session\" (the #2948 breaker), so such a lane\n *  can never be a lineage-follow target. byRef is the sharp test: blocked\n *  entries live in byRaw only and are unusable anyway. */\nfunction holdsRefs(s: Session): boolean {\n    return Object.keys(s.state.messageRefs?.byRef ?? {}).length > 0;\n}\n\n/** #2601: persona-fork descendants of a raw host id — sessions minted by the\n *  persona-anchor fork branch (`${rawId}|sub:${fp}`, persona-anchor.ts) that\n *  actually carried traffic, are fresh, AND hold refs (#2948: freshness alone\n *  selected ref-less aux lanes — see holdsRefs). Grouping by\n *  `id.split(\"|sub:\")[0]` is the house idiom (splitSessionWarnings, #2170\n *  canary). Sorted by lastSeen descending (listSessions order). */\nfunction personaDescendantsOf(baseId: string): Session[] {\n    if (baseId.includes(\"|sub:\")) return [];\n    const prefix = `${baseId}|sub:`;\n    const now = Date.now();\n    return listSessions().filter((s) => s.id.startsWith(prefix) && (s.stats?.requests ?? 0) > 0 && now - (s.lastSeen ?? 0) <= PERSONA_LINEAGE_FRESH_MS && holdsRefs(s));\n}\n\n/** #3397: highest ref number cited anywhere in the tool arguments\n *  (`mNNNNN`, the kernel's ref format) — recursive string walk. 0 = none. */\nfunction maxCitedRefNum(args: Record<string, unknown>): number {\n    let max = 0;\n    const visit = (v: unknown): void => {\n        if (typeof v === \"string\") {\n            for (const m of v.matchAll(/\\bm(\\d{5,})\\b/g)) max = Math.max(max, Number(m[1]));\n        } else if (Array.isArray(v)) {\n            for (const item of v) visit(item);\n        } else if (v !== null && typeof v === \"object\") {\n            for (const item of Object.values(v as Record<string, unknown>)) visit(item);\n        }\n    };\n    visit(args);\n    return max;\n}\n\n/** #3397: highest ref this session ever minted — byRef only grows (kernel\n *  id-never-reused contract), so a fork whose frontier sits below a cited\n *  ref cannot hold it. Same shape as stream.ts beyondFrontierNote. */\nfunction highestMintedRefNum(s: Session): number {\n    let max = 0;\n    for (const ref of Object.keys(s.state.messageRefs?.byRef ?? {})) {\n        const m = /^m(\\d{5,})$/.exec(ref);\n        if (m) max = Math.max(max, Number(m[1]));\n    }\n    return max;\n}\n\n/** #2601: the lineage's live session when the host-stamped RAW parent went\n *  FROZEN before the fork was born — the fork is that parent's continuation,\n *  and the host's compress/decompress/acp_status forwards (which keep\n *  stamping the raw id, because dsh cannot know bili derived a `|sub:` key)\n *  must follow it or strand on refs the frozen parent no longer holds — the\n *  #2601 \"every ref is unknown to this session\" breaker. The discriminator\n *  is BIRTH ORDER, not freshness: `fork.createdAt > parent.lastSeen` means\n *  the parent saw NO traffic after the fork was minted (frozen), so the\n *  fork's namespace is the only one the host's refs can live in. A parent\n *  that kept receiving turns after the fork was created (parallel persona\n *  forks / subagent lanes sharing the base id) stays authoritative — it is\n *  live, ITS namespace holds the refs, and re-routing the host's calls into\n *  a fork's namespace reproduces the same breaker in reverse (the dsh\n *  fusion-board incident: 8× cannot-anchor after the redirect; the\n *  pre-fix `fork.lastSeen > parent.lastSeen` rule also matches this shape —\n *  a still-active parent with a merely fresher parallel fork). Undefined\n *  when the parent is still the live session (switch back to the raw\n *  persona self-heals: the parent's lastSeen lands strictly after the\n *  fork's createdAt) or when no descendant holds refs (#2948: a ref-less\n *  aux lane is not a target — following it reproduces the same breaker it\n *  exists to cure; candidates are filtered in personaDescendantsOf, so a\n *  ref-holding sibling still wins over a fresher ref-less one).\n *  #3397: several forks can be live at once — dsh's chatty sidecar persona\n *  fires every few seconds while the owner conversation idles, so raw\n *  recency picked the WRONG fork and the call died on its small ref space\n *  (\"every ref is unknown\"). When the arguments cite refs, prefer a fork\n *  whose minted ref space can contain them (frontier ≥ max cited); with no\n *  fit or no citation the pick falls back to recency — identical to the\n *  pre-fix behavior, never worse. (#3647: the candidate filter below is\n *  birth-order — see the head of this comment.) */\nfunction livePersonaDescendant(parent: Session, maxCited?: number): Session | undefined {\n    if (parent.id.includes(\"|sub:\")) return undefined;\n    const cands = personaDescendantsOf(parent.id).filter((s) => (s.createdAt ?? 0) > (parent.lastSeen ?? 0));\n    if (cands.length === 0) return undefined;\n    const cited = maxCited ?? 0;\n    if (cited > 0) {\n        const fits = cands.filter((s) => highestMintedRefNum(s) >= cited);\n        if (fits.length > 0) return fits[0]; // listSessions order = lastSeen desc\n    }\n    return cands[0];\n}\n\n/** #2601: pick the witness session when it is a fresh `|sub:` fork of the\n *  stale parent — the #2601 incident shape: the host-stamped native caller\n *  (raw id) conflicts with the outbound witness because the tool call was\n *  minted in the fork's ref space. A lineage witness is not a spoof; a\n *  FOREIGN witness keeps the #2024 rules (refusal / native-caller override).\n *  Also follows when the caller itself is a fork whose parent minted the\n *  call (witness = base session) — same lineage, base of the same root. */\nfunction personaLineageWitness(witnessIds: Set<string>, resolvedId: string): Session | undefined {\n    const base = resolvedId.split(\"|sub:\")[0]!;\n    for (const w of witnessIds) {\n        if (w === resolvedId) continue;\n        if (!w.includes(\"|sub:\") && w !== base) continue; // witness must be in the same lineage root\n        if (w.includes(\"|sub:\") && w.split(\"|sub:\")[0] !== base) continue;\n        const s = peekSession(w);\n        if (s && (s.stats?.requests ?? 0) > 0 && Date.now() - (s.lastSeen ?? 0) <= PERSONA_LINEAGE_FRESH_MS) return s;\n    }\n    return undefined;\n}\n\nfunction forkReply(res: ServerResponse, status: number, body: unknown): void {\n    res.writeHead(status, { \"content-type\": \"application/json\" });\n    res.end(JSON.stringify(body));\n}\n\nexport async function handlePluginSnapshot(conversationId: string, res: ServerResponse): Promise<void> {\n    if (!conversationId) return forkReply(res, 400, { ok: false, code: \"INVALID_REQUEST\", error: \"conversationId is required\" });\n    const session = await resolveForkConversation(conversationId);\n    if (!session) return forkReply(res, 404, { ok: false, code: \"PARENT_NOT_FOUND\", error: \"unknown plugin conversation\" });\n    acquireInFlight(session);\n    try {\n        await waitForReconstructionReplicas(session); // #5188 round 3: don't race self-recovery into a 409\n        await withSessionLock(session, () => forkReply(res, 200, { ok: true, conversationId, ...forkSnapshot(session) }));\n    } catch (err) {\n        forkReply(res, 409, { ok: false, status: \"unavailable\", code: \"SNAPSHOT_UNAVAILABLE\", error: String(err) });\n    } finally {\n        releaseInFlight(session);\n    }\n}\n\nfunction parseForkRequest(payload: string): ForkRequest {\n    const value: unknown = JSON.parse(payload);\n    if (!value || typeof value !== \"object\" || Array.isArray(value)) throw new Error(\"expected fork object\");\n    const b = value as Record<string, unknown>;\n    const identifier = (v: unknown): v is string => typeof v === \"string\" && v.length > 0 && v.length <= 256 && v.trim() === v && !/[\\x00-\\x1f\\x7f]/.test(v);\n    const hash = (v: unknown): v is string => typeof v === \"string\" && /^[a-f0-9]{64}$/.test(v);\n    if (b.protocolVersion !== 1 && b.protocolVersion !== 2) throw new Error(\"unsupported fork protocolVersion (expected 1 or 2)\");\n    if (!identifier(b.parentConversationId) || !identifier(b.childConversationId) || !identifier(b.idempotencyKey) || !hash(b.parentRevision)) throw new Error(\"invalid fork identity/revision\");\n    if (b.parentConversationId === b.childConversationId) throw new Error(\"parent and child must differ\");\n    const point = b.branchPoint as Record<string, unknown> | null;\n    if (!point || !Number.isSafeInteger(point.messageCount) || (point.messageCount as number) < 0 || !hash(point.orderHash) || !Array.isArray(b.orderedMessages) || b.orderedMessages.length !== point.messageCount) throw new Error(\"invalid branchPoint/orderedMessages\");\n    const orderedMessages = b.orderedMessages.map((v: unknown): ForkIdentity => {\n        if (!v || typeof v !== \"object\") throw new Error(\"invalid ordered identity\");\n        const item = v as Record<string, unknown>;\n        // #2620: ref null = intentionally unaddressable (kernel-protected) prefix message.\n        if (!identifier(item.rawId) || !(item.ref === null || (typeof item.ref === \"string\" && /^m\\d{5,}$/.test(item.ref))) || !hash(item.identityHash)) throw new Error(\"invalid raw/ref identity\");\n        return { rawId: item.rawId, ref: item.ref, identityHash: item.identityHash };\n    });\n    return { protocolVersion: b.protocolVersion, parentConversationId: b.parentConversationId, childConversationId: b.childConversationId, parentRevision: b.parentRevision, branchPoint: { messageCount: point.messageCount as number, orderHash: point.orderHash }, orderedMessages, idempotencyKey: b.idempotencyKey };\n}\n\n/** [#2399 stage 2] omp/pi identity-register their session ids at session_start\n *  — BEFORE a fork child's first model request can trigger the extension-side\n *  adoption — so a fork POST for such a child arrives with the id already in\n *  registeredIds. That register carries the SAME parent the fork request\n *  declares, so it is a compatible lineage claim by the same host, not a rival\n *  child: allow the fork through and drop the register entry on success (the\n *  fork-created conversation then binds by the conversations map, exactly like\n *  a dsh-style child that never registered). A registered id WITHOUT a parent\n *  declaration, or with a different parent, stays a conflict. */\nfunction forkChildHeldBySameParent(child: string, parent: string): boolean {\n    return registeredIds.get(child)?.parentConversationId === parent;\n}\n\nexport async function handlePluginFork(payload: string, res: ServerResponse): Promise<void> {\n    let request: ForkRequest;\n    try { request = parseForkRequest(payload); }\n    catch (err) { return forkReply(res, 400, { ok: false, code: \"INVALID_REQUEST\", error: String(err) }); }\n    const requestHash = forkHash(request);\n    const replay = async (): Promise<boolean> => {\n        await getStore().recoverCompletedFork(request.childConversationId);\n        const existing = await resolveForkConversation(request.childConversationId);\n        if (!existing) return false;\n        const receipt = existing.metadata.publicForkReceipt as { requestHash?: unknown; response?: unknown } | undefined;\n        if (receipt?.requestHash === requestHash) forkReply(res, 200, { ...(receipt.response as Record<string, unknown>), replayed: true });\n        else forkReply(res, 409, { ok: false, code: \"CHILD_CONFLICT\", error: \"child conversation already exists or idempotency payload differs\" });\n        return true;\n    };\n    try { if (await replay()) return; }\n    catch (err) { return forkReply(res, 503, { ok: false, status: \"unavailable\", code: \"FORK_FAILED\", error: String(err) }); }\n    if (conversations.has(request.childConversationId) || pendingRegisters.some((r) => r.conversationId === request.childConversationId) || (registeredIds.has(request.childConversationId) && !forkChildHeldBySameParent(request.childConversationId, request.parentConversationId))) return forkReply(res, 409, { ok: false, code: \"CHILD_CONFLICT\", error: \"child conversation already registered\" });\n    const parent = await resolveForkConversation(request.parentConversationId);\n    if (!parent) return forkReply(res, 404, { ok: false, code: \"PARENT_NOT_FOUND\", error: \"parent conversation not found\" });\n    acquireInFlight(parent);\n    try {\n        await waitForReconstructionReplicas(parent); // #5188 round 3: don't race self-recovery into a 409\n        // #4911: async callback — the unified row clone below awaits the\n        // backend on network backends; withSessionLock accepts () => T |\n        // Promise<T>, so the lock scope and ordering are unchanged